const items = $input.all();
if (items.length === 0) {
  return [{ json: { count: 0 } }];
}
const allPlans = [];
const failed = [];

items.forEach(item => {
  const raw = item.json.property_raw_plan_json;
  let planArr;
  try {
    planArr = JSON.parse(raw);
  } catch (e) {
    failed.push({ id: item.json.id, reason: 'Raw Plan JSON khong parse duoc', preview: String(raw || '').slice(0, 120) });
    return;
  }
  if (!Array.isArray(planArr)) {
    failed.push({ id: item.json.id, reason: 'Raw Plan JSON khong phai array' });
    return;
  }
  planArr.forEach(p => {
    p.proposal_id = item.json.id;
    allPlans.push(p);
  });
});

if (failed.length && allPlans.length === 0) {
  throw new Error('Khong doc duoc proposal nao: ' + JSON.stringify(failed));
}

return [{ json: { count: allPlans.length, plans: allPlans, failed } }];

let data;
try {
  data = JSON.parse($input.first().json.choices[0].message.content);
} catch(e) {
  throw new Error('AI output is not valid JSON: ' + e.message);
}

data.proposal_id = $('Tách từng Bài viết').item.json.proposal_id;

// Platform mapping
const platformMap = { instagram: 'Instagram Feed', facebook: 'Facebook Page' };
let platformCap = platformMap[String(data.platform || '').toLowerCase()] || 'Instagram Feed';

// Format mapping
const formatMap = { carousel: 'Carousel', reel: 'Reel', story: 'Story', static: 'Static' };
let formatCap = formatMap[String(data.format || '').toLowerCase()] || 'Carousel';
data.format = formatCap;

// Framework bucket mapping to Content Pillar
const bucketToPillar = {
  '40_Pain': 'Operator credibility',
  '30_System': 'Systems education',
  '20_Proof': 'Proof & results',
  '10_Trang': 'Personal story'
};
data.content_pillar = bucketToPillar[data.framework_bucket] || 'Systems education';

// Build body blocks for Notion page
const SECTIONS = [
  ['📊 Framework Bucket', data.framework_bucket],
  ['📝 Tóm tắt bài viết', data.render_preview],
  ['🎨 Gợi ý Hình ảnh (Visual Suggestion)', data.visual_suggestion],
  ['✍️ Nội dung chi tiết (Content Text)', data.content_text]
];

const rt = (s) => ({ type: 'text', text: { content: s } });
const chunk = (s) => {
  const out = [];
  let t = String(s || '');
  if (!t) return ['(trống)'];
  while (t.length) {
    out.push(t.slice(0, 1900));
    t = t.slice(1900);
  }
  return out;
};

const body_blocks = [];
for (const [heading, content] of SECTIONS) {
  body_blocks.push({
    object: 'block',
    type: 'heading_3',
    heading_3: { rich_text: [rt(heading)] }
  });
  for (const piece of chunk(content)) {
    body_blocks.push({
      object: 'block',
      type: 'paragraph',
      paragraph: { rich_text: [rt(piece)] }
    });
  }
}

const capRichText = (s) => {
  const t = String(s || '');
  return t.length > 2000 ? t.slice(0, 1997) + '...' : t;
};

data.body_blocks = body_blocks;
data.platform_mapped = platformCap;
data.topic = capRichText(data.topic);
data.hook_used = capRichText(data.hook_used);

return [{ json: data }];
